transforms.code:
# v1.1.0 (P-PLN1 S3): the planner UI is served by the WebDev resource
# 'planner' (workmate.planner_api). Root-relative src = same origin on the
# LAN and through the reverse proxy. sid/pid let the API gate the request
# to THIS session and bridge 'wm-plan-open' back into THIS page.
# uid = session.custom.wmUserId (the startup identity, the same one every
# Workmate write uses); tok = HMAC(sid|uid) minted here in gateway scope,
# verified by planner_api - the browser cannot forge an actor.
try:
	proj = str(system.util.getProjectName() or '')
except:
	proj = ''
if not proj:
	proj = 'MainSCADA_Timberlands'
try:
	pid = str(self.page.props.pageId or '')
except:
	pid = ''
sid = str(value or '')
try:
	uid = int(self.session.custom.wmUserId or 0)
except:
	uid = 0
tok = ''
if uid > 0 and sid:
	try:
		tok = str(workmate.planner_api.token(sid, uid) or '')
	except:
		tok = ''
return ('/system/webdev/' + proj + '/planner/ui?sid=' + sid + '&pid=' + pid
	+ '&uid=' + str(uid) + '&tok=' + tok)
